function toolCard(t){const uses=state.usage[t.id]||0,fav=state.favorites.has(t.id),tags=(t.tags||[]).slice(0,3);return `<article class="card tool-card" data-open="${t.id}" tabindex="0" role="button" aria-label="Abrir ${esc(t.name)}"><div class="tool-card-top"><div class="tool-icon">${esc(t.icon)}</div><button class="fav ${fav?"on":""}" data-fav="${t.id}" aria-label="${fav?"Remover dos favoritos":"Adicionar aos favoritos"}">★</button></div><span class="tool-category">${esc(t.category)}</span><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p>${(t.kind==="custom_link"||t.kind==="internal_system")?`<button class="tool-edit-btn" data-tool-edit="${t.id}" title="Editar ferramenta">Editar</button>`:""}${tags.length?`<div class="tool-tags">${tags.map(x=>`<span>#${esc(x.name||x.slug)}</span>`).join("")}</div>`:""}<div class="tool-quick-actions"><button data-tool-action="launch" data-tool-id="${t.id}" ${t.launchUrl?"":"disabled"}>Abrir App</button><button data-tool-action="login" data-tool-id="${t.id}" ${t.loginUrl?"":"disabled"}>Copiar Login</button><button data-tool-action="notes" data-tool-id="${t.id}">Ver Notas</button></div><div class="tool-card-foot"><small class="tool-usage">${uses?`${uses} ${uses===1?"acesso":"acessos"}`:"Novo"}</small><span class="tool-open">Abrir <b>↗</b></span></div></article>`}
