function allowedModules(){if(!state.session)return["account"];if(state.access==null)return ACCESS_MODULES;if(isMaster())return ACCESS_MODULES;const list=Array.isArray(state.access?.modules)?state.access.modules:["account"];return ACCESS_MODULES.filter(id=>list.includes(id))}
function canAccess(id){return id==="account"||allowedModules().includes(id)}
function adminUsersPanel(){if(!isMaster())return"";const rows=state.adminUsers||[];return `<section class="card settings-card settings-panel" data-settings-panel="admin"><div class="settings-section-title"><div><span class="settings-kicker">MASTER / ADM</span><h2>Gestão de usuários</h2><p>Controle os módulos disponíveis para cada conta.</p></div><button class="ghost-action" id="adminRefreshUsers">Atualizar</button></div><div class="admin-users-list">${rows.length?rows.map(u=>`<article class="admin-user-row"><div class="admin-user-avatar">${esc((u.name||u.email||"U").slice(0,1).toUpperCase())}</div><div class="admin-user-copy"><strong>${esc(u.name||"Usuário")}</strong><small>${esc(u.email||"")}</small><span>${u.role==="master"?"MASTER":u.role==="admin"?"ADMIN":"USUÁRIO"} · ${u.active?"Ativo":"Bloqueado"} · ${(u.modules||[]).length} módulos</span></div><button type="button" class="ghost-action" data-admin-user="${u.user_id}">${u.role==="master"?"Visualizar":"Gerenciar"}</button></article>`).join(""):'<div class="settings-empty">Nenhum usuário encontrado.</div>'}</div></section>`}
