async function editUserAccess(userId){const u=state.adminUsers.find(x=>x.user_id===userId);if(!u)return;const master=u.role==="master",checks=NAV_ITEMS.map(x=>`<label class="admin-module-check"><input type="checkbox" value="${x[0]}" ${master||(u.modules||[]).includes(x[0])?"checked":""} ${master?"disabled":""}><span>${x[1]}<b>${x[2]}</b></span></label>`).join("");const r=await Swal.fire({title:master?"Conta Master":"Permissões do usuário",html:`<div class="admin-access-modal"><div class="admin-access-person"><strong>${esc(u.name||"Usuário")}</strong><small>${esc(u.email||"")}</small></div><label class="admin-access-status"><input id="adminUserActive" type="checkbox" ${u.active?"checked":""} ${master?"disabled":""}> Conta ativa</label><label class="admin-access-role">Função<select id="adminUserRole" ${master?"disabled":""}><option value="user" ${u.role==="user"?"selected":""}>Usuário</option><option value="admin" ${u.role==="admin"?"selected":""}>Administrador</option>${master?'<option value="master" selected>Master</option>':""}</select></label><p class="admin-access-help">Módulos liberados</p><div class="admin-module-grid">${checks}</div>${master?'<small class="admin-master-lock">A conta Master possui acesso total permanente.</small>':""}</div>`,showCancelButton:!master,confirmButtonText:master?"Fechar":"Salvar permissões",cancelButtonText:"Cancelar",preConfirm:()=>master?null:{active:document.querySelector("#adminUserActive")?.checked!==false,role:document.querySelector("#adminUserRole")?.value||"user",modules:[...document.querySelectorAll(".admin-module-check input:checked")].map(x=>x.value)}});if(!r.isConfirmed||master)return;try{await adminSetUserAccess(u.user_id,r.value.modules,r.value.active,r.value.role);await loadAdminUsers();toast("Permissões atualizadas");render()}catch(e){console.error(e);toast(e?.message||"Erro ao atualizar permissões","error")}}

function navOrder(){const saved=Array.isArray(state.settings.navOrder)?state.settings.navOrder:[];return[...saved.filter(id=>DEFAULT_NAV_ORDER.includes(id)),...DEFAULT_NAV_ORDER.filter(id=>!saved.includes(id))]}
function applyNavOrder(){const allowed=new Set(allowedModules()),order=navOrder().filter(id=>allowed.has(id)),rank=new Map(order.map((id,i)=>[id,i]));document.querySelectorAll("#nav [data-view]").forEach(el=>{const ok=allowed.has(el.dataset.view);el.hidden=!ok;if(!ok)return;el.style.order=rank.get(el.dataset.view)??99;const item=NAV_ITEMS.find(x=>x[0]===el.dataset.view);if(item)el.innerHTML=item[1]+"<span>"+item[2]+"</span>"});const mobile=order.filter(id=>id!=="settings"),primary=mobile.slice(0,3),more=mobile.slice(3);const bottom=document.querySelector(".bottom-nav");if(bottom){bottom.querySelectorAll("[data-view]").forEach(el=>el.remove());const moreBtn=$("#moreBtn");primary.forEach(id=>{const item=NAV_ITEMS.find(x=>x[0]===id);if(!item)return;const b=document.createElement("button");b.dataset.view=id;b.innerHTML=item[1]+"<span>"+(id==="dashboard"?"Início":item[2].replace("Ferramentas","Tools").replace("Fluxo Tools","Fluxo"))+"</span>";bottom.insertBefore(b,moreBtn)});if(moreBtn)moreBtn.hidden=more.length===0&&!allowed.has("settings")}const sheet=$("#moreSheet");if(sheet)sheet.innerHTML=[...more,...(allowed.has("settings")?["settings"]:[])].filter((v,i,a)=>a.indexOf(v)===i).map(id=>{const item=NAV_ITEMS.find(x=>x[0]===id);return item?'<button data-view="'+id+'">'+item[1]+' <span>'+item[2]+'</span></button>':""}).join("");document.querySelectorAll("[data-view]").forEach(b=>b.onclick=()=>{if(b.closest("#moreSheet"))b.closest("#moreSheet").hidden=true;goTo(b.dataset.view)})}
function fmtBytes(n){n=Number(n||0);if(!n)return"0 MB";return n>=1073741824?(n/1073741824).toFixed(2)+" GB":(n/1048576).toFixed(1)+" MB"}
async function refreshInfrastructure(){try{const live=await getInfrastructureStatus();if(live){state.infrastructure={...live,plan:"Free",planCode:"free_v3",branch:"production",branchState:"ready",logicalBytes:34062336,logicalLimitBytes:1073741824,region:"AWS us-east-2",compute:"0,25–2 CU · autoscaling"};store.set("td:infra",state.infrastructure);return true}}catch(e){console.warn("Infra status:",e)}return false}
function settingsView(){const order=navOrder(),autoSync=state.settings.autoSync!==false,compact=state.settings.compactNav===true,reduced=state.settings.reduceMotion===true,infra=state.infrastructure||{},pct=Math.min(100,Math.max(0,Number(infra.logicalBytes||0)/Number(infra.logicalLimitBytes||1073741824)*100)),startPage=state.settings.startPage||"dashboard";return `<div class="settings-page"><div class="settings-hero"><div><span class="eyebrow">CENTRAL DE CONTROLE</span><h1>Configurações</h1><p>Personalize o workspace, sincronização, dados e infraestrutura.</p></div><span class="settings-cloud">${state.session?"● Sincronizado na sua conta":"○ Somente neste dispositivo"}</span></div><div class="settings-layout"><aside class="settings-tabs"><button class="active" data-settings-tab="navigation">${navIcon("flow")}<span>Navegação</span></button><button data-settings-tab="interface">${navIcon("tools")}<span>Interface</span></button><button data-settings-tab="workspace">${navIcon("projects")}<span>Workspace</span></button><button data-settings-tab="system">${navIcon("settings")}<span>Sistema</span></button><button data-settings-tab="data">${navIcon("notes")}<span>Dados</span></button><button data-settings-tab="security">${navIcon("account")}<span>Segurança</span></button>${isMaster()?`<button data-settings-tab="admin">${navIcon("account")}<span>Administração</span></button>`:""}</aside><div class="settings-panels">
<section class="card settings-card settings-panel active" data-settings-panel="navigation"><div class="settings-section-title"><div><span class="settings-kicker">MENU</span><h2>Organize sua navegação</h2><p>Os 3 primeiros módulos aparecem na barra inferior do celular.</p></div><button class="ghost-action" id="resetNavOrder">Restaurar</button></div><div class="mobile-nav-preview"><small>PRÉVIA MOBILE</small><div>${order.slice(0,3).map(id=>{const item=NAV_ITEMS.find(x=>x[0]===id);return `<span>${item?.[1]||""}<b>${id==="dashboard"?"Início":item?.[2]||id}</b></span>`}).join("")}<span class="preview-more"><b>•••</b><em>Mais</em></span></div></div><div class="nav-order-list" id="navOrderList">${order.map((id,index)=>{const item=NAV_ITEMS.find(x=>x[0]===id);return `<article class="nav-order-item" draggable="true" data-nav-id="${id}"><span class="nav-position">${index+1}</span><i>${item?.[1]||""}</i><div class="nav-order-copy"><strong>${item?.[2]||id}</strong><small>${index<3?"Barra inferior no mobile":"Menu Mais"}</small></div><span class="nav-drag">⠿</span><div class="nav-move-actions"><button type="button" data-nav-up="${id}" ${index===0?"disabled":""}>↑</button><button type="button" data-nav-down="${id}" ${index===order.length-1?"disabled":""}>↓</button></div></article>`}).join("")}</div></section>
<section class="card settings-card settings-panel" data-settings-panel="interface"><div class="settings-section-title"><div><span class="settings-kicker">APARÊNCIA</span><h2>Interface</h2><p>Escolha o visual do sistema e ajuste densidade e movimento.</p></div></div><div class="theme-picker"><button type="button" data-theme-choice="black" class="${(state.settings.theme||"black")==="black"?"active":""}"><i class="theme-preview theme-black"></i><span><strong>All Black</strong><small>Preto com degradê · atual</small></span></button><button type="button" data-theme-choice="light" class="${state.settings.theme==="light"?"active":""}"><i class="theme-preview theme-light"></i><span><strong>Branco</strong><small>Claro, limpo e premium</small></span></button><button type="button" data-theme-choice="navy" class="${state.settings.theme==="navy"?"active":""}"><i class="theme-preview theme-navy"></i><span><strong>Azul Escuro</strong><small>Navy com degradê</small></span></button></div><div class="settings-option"><div><strong>Menu compacto</strong><small>Reduz o espaçamento do sidebar.</small></div><label class="td-switch"><input id="compactNavToggle" type="checkbox" ${compact?"checked":""}><span></span></label></div><div class="settings-option"><div><strong>Reduzir animações</strong><small>Transições mais discretas.</small></div><label class="td-switch"><input id="reduceMotionToggle" type="checkbox" ${reduced?"checked":""}><span></span></label></div><button class="settings-update-btn" id="resetInterface">Restaurar aparência padrão</button></section>
<section class="card settings-card settings-panel" data-settings-panel="workspace"><div class="settings-section-title"><div><span class="settings-kicker">WORKSPACE</span><h2>Inicialização</h2><p>Escolha onde o Tools Digital abre.</p></div></div><label class="settings-field"><span>Página inicial</span><select id="settingsStartPage">${NAV_ITEMS.filter(x=>x[0]!=="settings").map(x=>`<option value="${x[0]}" ${startPage===x[0]?"selected":""}>${x[2]}</option>`).join("")}</select></label><label class="settings-field"><span>Workspace padrão</span><select id="settingsWorkspace"><option value="">Automático</option>${state.workspaces.map(w=>`<option value="${w.id}" ${state.settings.activeWorkspace===w.id?"selected":""}>${esc(w.name||"Workspace")}</option>`).join("")}</select></label><small class="settings-hint">Essas preferências acompanham sua conta quando a sincronização está ativa.</small></section>
<section class="card settings-card settings-panel" data-settings-panel="system"><div class="settings-section-title"><div><span class="settings-kicker">SISTEMA</span><h2>Saúde e sincronização</h2><p>Estado do app, PWA e infraestrutura Neon.</p></div></div><div class="settings-option"><div><strong>Sincronização automática</strong><small>Salva alterações na nuvem.</small></div><label class="td-switch"><input id="settingsAutoSync" type="checkbox" ${autoSync?"checked":""}><span></span></label></div><div class="system-status-grid"><article><span class="system-status-dot ${navigator.onLine?"online":"offline"}"></span><div><small>CONEXÃO</small><strong>${navigator.onLine?"Online":"Offline"}</strong></div></article><article><span class="system-status-dot ${state.session?"online":"offline"}"></span><div><small>NUVEM</small><strong>${state.session?"Neon conectado":"Sessão local"}</strong></div></article><article><div><small>VERSÃO</small><strong>v${APP_VERSION}</strong></div></article></div><div class="neon-health-card"><div class="neon-health-head"><div><span class="settings-kicker">NEON DATABASE</span><h3>Saúde da infraestrutura</h3></div><span class="neon-health-badge">● ${infra.branchState==="ready"?"Operacional":"Monitorando"}</span></div><div class="neon-metrics"><article><small>PLANO</small><strong>${infra.plan||"Free"}</strong><span>${infra.planCode||"free_v3"}</span></article><article><small>BRANCH</small><strong>${infra.branch||"production"}</strong><span>${infra.branchState||"ready"}</span></article><article><small>BANCO</small><strong>${infra.database_size||"Atualizando…"}</strong><span>${infra.database_name||"neondb"}</span></article><article><small>ARMAZENAMENTO</small><strong>${fmtBytes(infra.logicalBytes)} / 1 GB</strong><span>${pct.toFixed(1)}% do limite lógico</span></article></div><div class="neon-storage-bar"><span style="width:${pct}%"></span></div><div class="settings-system-row"><span>PostgreSQL</span><strong>${infra.postgres_version?.split(" ")[0]||"18"}</strong></div><div class="settings-system-row"><span>Região</span><strong>${infra.region||"AWS us-east-2"}</strong></div><div class="settings-system-row"><span>Compute</span><strong>${infra.compute||"0,25–2 CU · autoscaling"}</strong></div><div class="settings-system-row"><span>Última leitura do banco</span><strong>${infra.checked_at?new Date(infra.checked_at).toLocaleString("pt-BR"):"Aguardando"}</strong></div><small class="neon-metric-note">Tamanho do banco é consultado ao vivo por uma função segura. Plano, região e limite lógico usam metadados administrativos conhecidos do projeto.</small></div><div class="settings-system-actions"><button id="settingsRefreshInfra"><strong>Atualizar saúde do Neon</strong><small>Fazer nova leitura do banco</small></button><button id="settingsSyncNow"><strong>Sincronizar agora</strong><small>Buscar dados mais recentes da nuvem</small></button><button id="settingsUpdateBtn"><strong>Buscar atualizações</strong><small>Verificar nova versão</small></button><button id="settingsClearCache"><strong>Limpar cache do app</strong><small>Não apaga seus dados</small></button><button id="settingsDiagnostics"><strong>Diagnóstico do sistema</strong><small>PWA, rede, armazenamento e sincronização</small></button></div></section>
<section class="card settings-card settings-panel" data-settings-panel="data"><div class="settings-section-title"><div><span class="settings-kicker">DADOS</span><h2>Backup e portabilidade</h2><p>Tenha uma cópia dos seus dados do workspace.</p></div></div><div class="data-summary-grid"><article><strong>${state.notes.length}</strong><span>Notas</span></article><article><strong>${state.transactions.length}</strong><span>Transações visíveis</span></article><article><strong>${state.cloudProjects.length}</strong><span>Projetos</span></article><article><strong>${state.workspaces.length}</strong><span>Workspaces</span></article></div><div class="settings-system-actions"><button id="settingsExportData"><strong>Exportar backup</strong><small>Baixar JSON com dados e preferências locais</small></button><button id="settingsImportData"><strong>Importar backup</strong><small>Restaurar notas, preferências e dados compatíveis</small></button><input id="settingsImportFile" type="file" accept="application/json,.json" hidden></div><small class="settings-hint">A importação só acontece após sua confirmação e não altera a estrutura do banco.</small></section>
<section class="card settings-card settings-panel" data-settings-panel="security"><div class="settings-section-title"><div><span class="settings-kicker">SEGURANÇA</span><h2>Sessão e conta</h2><p>Informações da sessão atual.</p></div></div><div class="settings-system-row"><span>Conta</span><strong>${esc(state.session?.user?.email||"Sem sessão")}</strong></div><div class="settings-system-row"><span>Autenticação</span><strong>${state.session?"Ativa":"Inativa"}</strong></div><div class="settings-system-row"><span>Conexão segura</span><strong>${location.protocol==="https:"?"HTTPS":"Verificar"}</strong></div><button class="settings-danger-btn" id="settingsLogout" ${state.session?"":"disabled"}>Sair deste dispositivo</button></section>${adminUsersPanel()}\n</div></div></div>`}
async function persistSettings(message="Configurações atualizadas"){store.set("td:settings",state.settings);applyInterfaceSettings();applyNavOrder();if(state.session)try{await saveSettings(state.settings)}catch(e){console.warn("Settings cloud:",e);toast("Salvo neste dispositivo · nuvem pendente","error");return}toast(message)}
function applyInterfaceSettings(){const theme=["black","light","navy"].includes(state.settings.theme)?state.settings.theme:"black";document.documentElement.dataset.theme=theme;document.body.classList.toggle("compact-nav",state.settings.compactNav===true);document.body.classList.toggle("reduce-motion",state.settings.reduceMotion===true)}
async function saveNavOrder(order){state.settings.navOrder=order;await persistSettings("Ordem do menu atualizada")}
function exportSettingsBackup(){const payload={format:"tools-digital-backup",version:APP_VERSION,exportedAt:new Date().toISOString(),notes:state.notes,transactions:state.transactions.filter(t=>!state.session||!t.ownerId||t.ownerId===state.session.user.id),favorites:[...state.favorites],usage:state.usage,settings:state.settings};const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="tools-digital-backup-"+new Date().toISOString().slice(0,10)+".json";a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
async function importSettingsBackup(file){let data;try{data=JSON.parse(await file.text())}catch{toast("Backup inválido","error");return}if(data?.format!=="tools-digital-backup"){toast("Arquivo não pertence ao Tools Digital","error");return}const ok=(await Swal.fire({title:"Restaurar backup?",text:"Os dados compatíveis deste arquivo substituirão o cache atual e serão sincronizados com sua conta.",icon:"warning",showCancelButton:true,confirmButtonText:"Restaurar",cancelButtonText:"Cancelar",background:"#080808",color:"#fff"})).isConfirmed;if(!ok)return;state.notes=normalizeIds(Array.isArray(data.notes)?data.notes:[]);state.transactions=normalizeIds(Array.isArray(data.transactions)?data.transactions:[]);state.favorites=new Set(Array.isArray(data.favorites)?data.favorites:[]);state.usage=data.usage&&typeof data.usage==="object"?data.usage:{};state.settings={...state.settings,...(data.settings||{})};store.set("td:notes",state.notes);store.set("td:transactions",state.transactions);store.set("td:favorites",[...state.favorites]);store.set("td:usage",state.usage);store.set("td:settings",state.settings);if(state.session){store.set("td:sync:pending",true);queueCloudSync();await saveSettings(state.settings)}toast("Backup restaurado","success");render()}
function bindSettings(){document.querySelectorAll("[data-settings-tab]").forEach(btn=>btn.onclick=async()=>{document.querySelectorAll("[data-settings-tab]").forEach(x=>x.classList.toggle("active",x===btn));document.querySelectorAll("[data-settings-panel]").forEach(x=>x.classList.toggle("active",x.dataset.settingsPanel===btn.dataset.settingsTab));if(btn.dataset.settingsTab==="system"&&!state.infrastructure){await refreshInfrastructure();render()}});const list=$("#navOrderList");if(list){let dragged=null;const commit=async()=>{await saveNavOrder([...list.querySelectorAll("[data-nav-id]")].map(x=>x.dataset.navId));render()};list.querySelectorAll("[data-nav-id]").forEach(row=>{row.addEventListener("dragstart",()=>{dragged=row;row.classList.add("dragging")});row.addEventListener("dragend",()=>{row.classList.remove("dragging");dragged=null});row.addEventListener("dragover",e=>{e.preventDefault();if(!dragged||dragged===row)return;const rect=row.getBoundingClientRect();list.insertBefore(dragged,e.clientY<rect.top+rect.height/2?row:row.nextSibling)})});list.addEventListener("drop",e=>{e.preventDefault();commit()});list.querySelectorAll("[data-nav-up],[data-nav-down]").forEach(btn=>btn.onclick=async()=>{const row=btn.closest("[data-nav-id]");if(btn.dataset.navUp!==undefined&&row.previousElementSibling)list.insertBefore(row,row.previousElementSibling);else if(row.nextElementSibling)list.insertBefore(row.nextElementSibling,row);await commit()})}$("#resetNavOrder")?.addEventListener("click",async()=>{await saveNavOrder([...DEFAULT_NAV_ORDER]);render()});document.querySelectorAll("[data-theme-choice]").forEach(btn=>btn.onclick=async()=>{state.settings.theme=btn.dataset.themeChoice;applyInterfaceSettings();document.querySelectorAll("[data-theme-choice]").forEach(x=>x.classList.toggle("active",x===btn));await persistSettings("Tema atualizado")});$("#compactNavToggle")?.addEventListener("change",async e=>{state.settings.compactNav=e.target.checked;await persistSettings()});$("#reduceMotionToggle")?.addEventListener("change",async e=>{state.settings.reduceMotion=e.target.checked;await persistSettings()});$("#resetInterface")?.addEventListener("click",async()=>{state.settings.theme="black";state.settings.compactNav=false;state.settings.reduceMotion=false;await persistSettings("Aparência restaurada");render()});$("#settingsStartPage")?.addEventListener("change",async e=>{state.settings.startPage=e.target.value;await persistSettings("Página inicial atualizada")});$("#settingsWorkspace")?.addEventListener("change",async e=>{state.settings.activeWorkspace=e.target.value;await persistSettings("Workspace padrão atualizado")});$("#settingsAutoSync")?.addEventListener("change",async e=>{state.settings.autoSync=e.target.checked;await persistSettings("Sincronização atualizada")});$("#settingsRefreshInfra")?.addEventListener("click",async()=>{const ok=await refreshInfrastructure();toast(ok?"Saúde do Neon atualizada":"Métrica dinâmica aguardando ativação","info");render()});$("#settingsUpdateBtn")?.addEventListener("click",()=>checkForUpdates(true));$("#settingsSyncNow")?.addEventListener("click",async()=>{if(!state.session)return toast("Entre na sua conta para sincronizar","info");try{await hydrateCloud();await loadAccountData();toast("Dados sincronizados","success");render()}catch{toast("Não foi possível sincronizar","error")}});$("#settingsClearCache")?.addEventListener("click",async()=>{try{const keys=await caches.keys();await Promise.all(keys.filter(k=>k.startsWith("tools-digital-")).map(k=>caches.delete(k)));toast("Cache temporário limpo","success");if(swRegistration)await swRegistration.update()}catch{toast("Não foi possível limpar o cache","error")}});$("#settingsDiagnostics")?.addEventListener("click",async()=>{const sw=!!navigator.serviceWorker?.controller,storage=await navigator.storage?.estimate?.(),used=storage?.usage?Math.round(storage.usage/1048576):null,quota=storage?.quota?Math.round(storage.quota/1048576):null;await Swal.fire({title:"Diagnóstico do sistema",html:`<div class="system-diagnostics"><div><span>Versão</span><strong>v${APP_VERSION}</strong></div><div><span>Conexão</span><strong>${navigator.onLine?"Online":"Offline"}</strong></div><div><span>Neon</span><strong>${state.session?"Conectado":"Sem sessão"}</strong></div><div><span>Service Worker</span><strong>${sw?"Ativo":"Inativo"}</strong></div><div><span>Modo PWA</span><strong>${matchMedia("(display-mode: standalone)").matches?"Instalado":"Navegador"}</strong></div><div><span>Cache usado</span><strong>${used===null?"Indisponível":used+" MB"+(quota?" / "+quota+" MB":"")}</strong></div></div>`,confirmButtonText:"Fechar",background:"#080808",color:"#fff"})});$("#settingsExportData")?.addEventListener("click",exportSettingsBackup);$("#settingsImportData")?.addEventListener("click",()=>$("#settingsImportFile")?.click());$("#settingsImportFile")?.addEventListener("change",e=>e.target.files?.[0]&&importSettingsBackup(e.target.files[0]));$("#settingsLogout")?.addEventListener("click",async()=>{await signOut();clearToolCockpit();clearSessionState(state);view="account";toast("Sessão encerrada");render()});$("#adminRefreshUsers")?.addEventListener("click",async()=>{await loadAdminUsers();render()});document.querySelectorAll("[data-admin-user]").forEach(b=>b.onclick=()=>editUserAccess(b.dataset.adminUser))}

const ensureLocalIds=()=>{let changed=false;state.notes=state.notes.map(n=>{if(n.id)return n;changed=true;return{...n,id:crypto.randomUUID?.()||Date.now()+"-"+Math.random()}});state.transactions=state.transactions.map(t=>{if(t.id)return t;changed=true;return{...t,id:crypto.randomUUID?.()||Date.now()+"-"+Math.random(),category:t.category||"Geral"}});if(changed){store.set("td:notes",state.notes);store.set("td:transactions",state.transactions)}};ensureLocalIds();
function noteTags(){return [...new Set(state.notes.flatMap(n=>n.tags||[]))].sort()}
function notesView(){return secondBrainView(state.notes)}
function sortNotes(list,sort="updated"){return [...list].sort((a,b)=>{if(a.pinned!==b.pinned)return a.pinned?-1:1;if(sort==="title")return(a.title||"").localeCompare(b.title||"","pt-BR");if(sort==="created")return(b.createdAt||0)-(a.createdAt||0);return(b.updatedAt||b.createdAt||0)-(a.updatedAt||a.createdAt||0)})}
function renderNotes(list){return list.map(n=>`<article class="card note-card ${n.pinned?"pinned":""}" data-note="${n.id}" tabindex="0"><div class="note-top"><div><button class="note-pin ${n.pinned?"on":""}" data-note-pin="${n.id}" title="Fixar nota">⌖</button><button class="note-favorite ${n.favorite?"on":""}" data-note-fav="${n.id}" title="Favoritar">★</button></div><button data-note-menu="${n.id}" aria-label="Editar nota">•••</button></div><button class="note-open" data-note-open="${n.id}"><h3>${esc(n.title||"Sem título")}</h3><p>${esc(n.body||"")}</p></button><div class="note-tags-inline">${(n.tags||[]).slice(0,4).map(t=>`<span>#${esc(t)}</span>`).join("")}</div><small class="note-date">Atualizada ${new Date(n.updatedAt||n.createdAt).toLocaleDateString("pt-BR")}</small></article>`).join("")}
async function noteDialog(note=null){if(!window.Swal)return;const r=await Swal.fire({title:note?"Editar nota":"Nova nota",width:640,customClass:{popup:"td-modal td-note-modal",title:"td-modal-title",htmlContainer:"td-modal-body",actions:"td-modal-actions",confirmButton:"td-modal-confirm",cancelButton:"td-modal-cancel"},html:`<div class="td-field"><label>Título</label><input id="swNoteTitle" maxlength="100" placeholder="Ex.: Ideias para o projeto" value="${esc(note?.title||"")}"></div><div class="td-field"><label>Conteúdo</label><textarea id="swNoteBody" class="note-editor" maxlength="6000" placeholder="Escreva sua nota...">${esc(note?.body||"")}</textarea></div><div class="td-field"><label>Tags <span>separe por vírgulas</span></label><input id="swNoteTags" maxlength="160" placeholder="projeto, ideia, importante" value="${esc((note?.tags||[]).join(", "))}"></div>`,showCancelButton:true,confirmButtonText:note?"Salvar alterações":"Salvar nota",cancelButtonText:"Cancelar",background:"#080808",color:"#fff",confirmButtonColor:"#fff",preConfirm:()=>{const title=document.querySelector("#swNoteTitle").value.trim(),body=document.querySelector("#swNoteBody").value.trim(),tags=[...new Set(document.querySelector("#swNoteTags").value.split(",").map(x=>x.trim().toLowerCase()).filter(Boolean))].slice(0,8);if(!title&&!body){Swal.showValidationMessage("Escreva um título ou conteúdo");return false}return{title,body,tags}}});if(!r.isConfirmed)return;const now=Date.now();if(note)Object.assign(note,r.value,{updatedAt:now});else state.notes.unshift({id:makeCloudId(),...r.value,pinned:false,favorite:false,createdAt:now,updatedAt:now});store.set("td:notes",state.notes);store.set("td:sync:pending",true);queueCloudSync();audit("Notas",note?"edit":"create",r.value.title||"Sem título");toast(note?"Nota atualizada":"Nota criada");render()}
