function renderBreakdown(list){const m={};list.filter(t=>t.amount<0).forEach(t=>m[t.category||"Geral"]=(m[t.category||"Geral"]||0)+Math.abs(t.amount));const total=Object.values(m).reduce((a,b)=>a+b,0);return Object.entries(m).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([k,v])=>`<div><span><b>${esc(k)}</b><small>${money(v)}</small></span><i><em style="width:${total?Math.round(v/total*100):0}%"></em></i></div>`).join("")}
