async function importFinance(file){try{const data=JSON.parse(await file.text()),list=Array.isArray(data)?data:data.transactions;if(!Array.isArray(list))throw 0;const valid=list.filter(t=>t&&typeof t==="object"&&t.description&&Number.isFinite(Number(t.amount))).map(t=>({...t,id:/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(t.id||"")?t.id:makeCloudId(),amount:Number(t.amount),category:t.category||"Geral",createdAt:Number(t.createdAt)||Date.now(),updatedAt:Number(t.updatedAt)||Number(t.createdAt)||Date.now()}));state.transactions=[...valid,...state.transactions.filter(t=>!valid.some(x=>x.id===t.id))];store.set("td:transactions",state.transactions);store.set("td:sync:pending",true);queueCloudSync();audit("Financeiro","import",valid.length+" transações");toast(valid.length+" transações importadas");render()}catch{toast("Backup financeiro inválido","error")}}
function exportFinance(){const rows=[["Data","Descrição","Categoria","Tipo","Valor"],...[...state.transactions].sort((a,b)=>b.createdAt-a.createdAt).map(t=>[new Date(t.createdAt).toLocaleDateString("pt-BR"),t.description,t.category||"Geral",t.amount>0?"Entrada":"Saída",(t.amount/100).toFixed(2).replace(".",",")])];const csv=rows.map(r=>r.map(v=>'"'+String(v??"").replaceAll('"','""')+'"').join(";")).join("\n");downloadFile("tools-digital-financeiro-"+new Date().toISOString().slice(0,10)+".csv","\ufeff"+csv,"text/csv;charset=utf-8");toast("Financeiro exportado em CSV")}
