async function forgotPassword(){const r=await Swal.fire({title:"Recuperar senha",input:"email",inputPlaceholder:"seu@email.com",showCancelButton:true,confirmButtonText:"Enviar recuperação",background:"#080808",color:"#fff"});if(!r.isConfirmed)return;try{await requestPasswordReset(r.value,location.origin+location.pathname);toast("Verifique seu e-mail")}catch(e){toast(e?.message||"Não foi possível enviar a recuperação","error")}}
async function authenticate(mode){
 const name=$("#authName")?.value.trim()||"",email=$("#authEmail")?.value.trim()||"",password=$("#authPassword")?.value||"",confirm=$("#authPasswordConfirm")?.value||"",error=$("#authFormError");
 const fail=m=>{if(error){error.textContent=m;error.hidden=false}return false};
 if(mode==="signup"&&!name)return fail("Informe seu nome.");
 if(!email || !email.includes("@") || !email.slice(email.lastIndexOf("@")+1).includes("."))return fail("Informe um e-mail válido.");
 if(password.length<8)return fail("A senha precisa ter pelo menos 8 caracteres.");
 if(mode==="signup"&&password!==confirm)return fail("As senhas não conferem.");
 const btn=mode==="signup"?$("#signupSubmit"):$("#loginSubmit");if(btn){btn.disabled=true;btn.textContent=mode==="signup"?"Criando conta…":"Entrando…"}if(error)error.hidden=true;
 try{
  if(mode==="signup")await signUp(name,email,password);else await signIn(email,password);
  state.session=await getSession();
  if(!state.session){if(mode==="signup"){authMode="login";toast("Conta criada. Entre com seu e-mail e senha.","success");render();return}throw new Error("Sessão não iniciada. Tente novamente.")}
  if(mode==="signup"){
   state.notes=[];state.transactions=[];state.favorites=new Set();state.usage={};state.recent=[];state.cloudProjects=[];state.workspaces=[];state.cloudFlows=[];state.cloudActivity=[];
   store.set("td:notes",[]);store.set("td:transactions",[]);store.set("td:favorites",[]);store.set("td:usage",{});store.set("td:recent",[]);store.set("td:sync:pending",false);
   await loadAccountData();
  }else{
   await hydrateCloud({firstSync:false});await loadAccountData();
  }
  toast(mode==="signup"?"Conta criada com sucesso":"Login realizado");goTo("dashboard")
 }catch(e){fail(authMessage(e))}
 finally{if(btn){btn.disabled=false;btn.textContent=mode==="signup"?"Criar minha conta":"Entrar"}}
}
function authMessage(e){const m=String(e?.message||e||"").toLowerCase();if(m.includes("already")||m.includes("exist")||m.includes("registered"))return"Este e-mail já possui uma conta.";if(m.includes("invalid")||m.includes("credential")||m.includes("password"))return"E-mail ou senha inválidos.";if(m.includes("network")||m.includes("fetch"))return"Não foi possível conectar ao servidor. Verifique sua internet.";return e?.message||"Não foi possível concluir a autenticação."}
let authMode="login";



async function loadAccountData(){if(!state.session)return;try{const sessionEmail=(state.session?.user?.email||"").toLowerCase();const access=await getCurrentModuleAccess();state.access=access||(sessionEmail===MASTER_EMAIL?{email:sessionEmail,role:"master",active:true,modules:ACCESS_MODULES}:null);if(access?.active===false)throw new Error("Conta sem acesso ao sistema");const [profile,workspaces,cloudProjects,cloudActivity,cloudFlows,settings]=await Promise.all([getProfile(),listWorkspaces(),listCloudProjects(),listActivity(),listFlows(),listSettings()]);const financeAllowed=canAccess("finance");const [entities,members,accounts]=financeAllowed?await Promise.all([listFinanceEntities(),listFinanceMembers(),listFinanceAccounts()]):[[],[],[]];state.profile=profile;state.workspaces=workspaces;state.cloudProjects=cloudProjects;state.cloudActivity=cloudActivity;state.cloudFlows=cloudFlows;state.settings={...state.settings,...settings};store.set("td:settings",state.settings);financeEntities=entities;financeMembers=members;financeAccounts=accounts;financeInvites=canAccess("finance")?await listFinanceInvites().catch(()=>[]):[];await loadAdminUsers()}catch(e){console.warn("Account data:",e);if((state.session?.user?.email||"").toLowerCase()===MASTER_EMAIL){state.access={email:MASTER_EMAIL,role:"master",active:true,modules:ACCESS_MODULES};await loadAdminUsers().catch(()=>{})}}}
